export interface TestRecord {
  year: number | string; // 年度（数字または号外用の文字列）
  testType: 'main' | 'makeup'; // 本試験 or 追試験
  subject: string; // 教科（実態教科名）
  questionPdf: string; // 問題PDFファイル名
  answerPdf: string; // 解答PDFファイル名
  audio: string; // 音声ファイル名（空文字列の場合あり）
  pdfState: 1 | 2 | 3; // PDF状態: 1=正常, 2=一部欠損, 3=完全欠損
}

// 拡張されたTestRecord（表示用に分類用教科名と本質教科名を含む）
export interface EnhancedTestRecord extends TestRecord {
  categorySubject: string; // 分類用教科名
  essentialSubject: string; // 本質教科名
  priority: number; // ソート用の優先順位
  questionExists: boolean;
  answerExists: boolean;
  audioExists: boolean;
}

// 教科の順序定義
export const SUBJECT_ORDER = [
  '国語',
  '数学①',
  '数学②',
  '理科',
  '理科基礎',
  '社会',
  '英語（Reading）',
  '英語（Listening）',
  '情報',
  'その他'
] as const;

// フィルタリング対象の教科と本質教科名のマッピング
export const FILTERABLE_SUBJECTS = {
  '理科': ['物理', '化学', '生物', '地学'],
  '理科基礎': ['物理基礎', '化学基礎', '生物基礎', '地学基礎'],
  '社会': ['地理', '日本史', '世界史', '現代社会', '倫理', '政経', '倫理政経', '現代社会'],
  'その他': [] // その他は動的に決定
} as const;

type PdfState = 1 | 2 | 3;

const PDF_BASE_URL = (import.meta.env.VITE_PDF_BASE_URL ?? "")
  .trim()
  .replace(/\/+$/, "");

function buildCdnUrl(pathOrName: string): string | null {
  if (!PDF_BASE_URL) return null;

  const normalized = pathOrName
    .trim()
    .replace(/^\/+/, "")
    .replace(/^pdfs\//, "");

  if (!normalized) return null;

  const encodedPath = normalized
    .split("/")
    .filter(Boolean)
    .map((part) => encodeURIComponent(part))
    .join("/");

  return `${PDF_BASE_URL}/${encodedPath}`;
}

function existsInPublicPdfs(pathOrName: string | undefined | null): boolean {
  const s = (pathOrName ?? "").trim();
  return s.length > 0;
}

function severityFromExistingFiles(files: string[]): PdfState {
  const targets = files.map(s => (s ?? "").trim()).filter(s => s.length > 0);
  if (targets.length === 0) return 1;

  let missing = 0;
  for (const name of targets) {
    if (!existsInPublicPdfs(name)) missing++;
  }

  if (missing === 0) return 1;
  if (missing === targets.length) return 3;
  return 2;
}

function applyFileExistenceOverride(manual: PdfState, files: string[]): PdfState {
  const derived = severityFromExistingFiles(files);
  return Math.max(manual, derived) as PdfState; // 2→1 は起こらない
}

// TSVデータをパースしてTestRecordの配列に変換
function parseTSV(tsv: string): TestRecord[] {
  const lines = tsv.split('\n').filter(line => line.trim());
  return lines.map(line => {
    const parts = line.split('\t');
    if (parts.length !== 7) {
      console.error('Invalid TSV line:', line);
      return null;
    }

    const [yearStr, testType, subject, questionPdf, answerPdf, audio, pdfStateStr] = parts;

    // 年度を数値または文字列に変換
    const year = /^\d+$/.test(yearStr) ? parseInt(yearStr, 10) : yearStr;

    // testTypeのバリデーション
    if (testType !== 'main' && testType !== 'makeup') {
      console.error('Invalid testType:', testType);
      return null;
    }

    // pdfStateを数値に変換
    const manualPdfState = parseInt(pdfStateStr, 10) as 1 | 2 | 3;
    if (![1, 2, 3].includes(manualPdfState)) {
      console.error('Invalid pdfState:', pdfStateStr);
      return null;
    }

    // 実ファイルの存在に基づき、より深刻な場合だけ上書き（2→1はしない）
    const pdfStateFinal = applyFileExistenceOverride(
      manualPdfState,
      [questionPdf, answerPdf, audio]
    );

    return {
      year,
      testType,
      subject,
      questionPdf,
      answerPdf,
      audio: audio || '',
      pdfState: pdfStateFinal,
    };
  }).filter((record): record is TestRecord => record !== null);
}

// データベース（パース済み）
export const testDatabase: TestRecord[] = parseTSV(DATABASE_TSV);

/**
 * DBの pdfPath / audioPath を CDN URL に変換する
 * - "pdfs/foo.pdf" -> "https://.../foo.pdf"
 * - "foo.pdf" -> "https://.../foo.pdf"
 */
export function resolvePublicPdfUrl(pathOrName: string | undefined | null): string | null {
  const s = (pathOrName ?? "").trim();
  if (!s) return null;

  return buildCdnUrl(s);
}

// TestRecordをEnhancedTestRecordに変換
// essential が配列の場合は、各要素に対して個別のEnhancedTestRecordを生成
export function enhanceTestRecord(record: TestRecord): EnhancedTestRecord[] {
  const mapping = SUBJECT_MAPPING[record.subject];
  if (!mapping) {
    console.warn(`Unknown subject: ${record.subject}`);
    return [{
      ...record,
      categorySubject: 'その他',
      essentialSubject: record.subject,
      priority: 999,
      questionExists: existsInPublicPdfs(record.questionPdf),
      answerExists: existsInPublicPdfs(record.answerPdf),
      audioExists: existsInPublicPdfs(record.audio),
    }];
  }

  // essential が配列かどうかを判定
  const essentials = Array.isArray(mapping.essential) ? mapping.essential : [mapping.essential];

  // 各essentialに対してEnhancedTestRecordを生成
  return essentials.map((essential) => {
    // 優先順位を決定（理科・理科基礎・社会・その他は本質教科名で決定）
    let priority = 1;
    const filterableKeys = Object.keys(FILTERABLE_SUBJECTS) as Array<keyof typeof FILTERABLE_SUBJECTS>;

    for (const key of filterableKeys) {
      const essentialsInCategory = FILTERABLE_SUBJECTS[key];
      const index = essentialsInCategory.indexOf(essential as any);
      if (index !== -1) {
        priority = index + 1;
        break;
      }
    }

    // その他の教科の場合は動的に優先順位を決定
    if (mapping.category === 'その他') {
      const otherSubjects = getOtherSubjectOrder();
      priority = otherSubjects.indexOf(essential) + 1;
    }

    return {
      ...record,
      categorySubject: mapping.category,
      essentialSubject: essential,
      priority,
      questionExists: existsInPublicPdfs(record.questionPdf),
      answerExists: existsInPublicPdfs(record.answerPdf),
      audioExists: existsInPublicPdfs(record.audio),
    };
  });
}

// 拡張されたデータベースを取得
export function getEnhancedDatabase(): EnhancedTestRecord[] {
  return testDatabase.flatMap(enhanceTestRecord);
}

// ソート関数
export function sortTestRecords(records: EnhancedTestRecord[]): EnhancedTestRecord[] {
  return records.sort((a, b) => {
    // 1. 年度（数字のものを新しい順、文字列は最後）
    const yearA = typeof a.year === 'number' ? a.year : -Infinity;
    const yearB = typeof b.year === 'number' ? b.year : -Infinity;
    if (yearA !== yearB) return yearB - yearA;

    // 2. 教科順
    const subjectIndexA = SUBJECT_ORDER.indexOf(a.categorySubject as any);
    const subjectIndexB = SUBJECT_ORDER.indexOf(b.categorySubject as any);
    if (subjectIndexA !== subjectIndexB) return subjectIndexA - subjectIndexB;

    // 3. 優先順位
    if (a.priority !== b.priority) return a.priority - b.priority;

    // 4. 本試験・追試験
    if (a.testType !== b.testType) {
      return a.testType === 'main' ? -1 : 1;
    }

    return 0;
  });
}

// 年度一覧を取得（重複排除）
export function getYearList(): (number | string)[] {
  const years = Array.from(new Set(testDatabase.map(r => r.year)));
  const numericYears = years.filter(y => typeof y === 'number').sort((a, b) => (b as number) - (a as number));
  const specialYears = years.filter(y => typeof y === 'string');
  return [...numericYears, ...specialYears];
}

// 教科一覧を取得（SUBJECT_ORDERに従う）
export function getSubjectList(): string[] {
  const enhanced = getEnhancedDatabase();
  const subjects = Array.from(new Set(enhanced.map(r => r.categorySubject)));
  return SUBJECT_ORDER.filter(s => subjects.includes(s));
}

function applyPdfStateOverride(record: TestRecord): TestRecord {
  const override = getOverrideForRecord(record); // 2 or 3 or null
  if (!override) return record;

  const finalState = Math.max(record.pdfState, override) as PdfState;
  if (finalState === record.pdfState) return record;

  return { ...record, pdfState: finalState };
}

// もし testDatabase 自体も使われているなら、追加APIとして別名も出せる
export function getDatabaseWithVerifiedPdfState(): TestRecord[] {
  return testDatabase.map(applyPdfStateOverride);
}

// その他の教科のフィルタリング順序を取得（SUBJECT_MAPPING定義順）
export function getOtherSubjectOrder(): string[] {
  const otherSubjects: string[] = [];
  const seen = new Set<string>();

  // SUBJECT_MAPPINGの定義順で「その他」カテゴリの科目を取得
  for (const [subjectName, mapping] of Object.entries(SUBJECT_MAPPING)) {
    if (mapping.category === 'その他') {
  const essentials = Array.isArray(mapping.essential)
    ? mapping.essential
    : [mapping.essential];

  for (const essential of essentials) {
    if (!seen.has(essential)) {
          otherSubjects.push(essential);
          seen.add(essential);
        }
      }
    }
  }

  return otherSubjects;
}
